<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{apiRequest}from'@/api/client';import{logout}from'@/api/auth';const currentPassword=ref(''),newPassword=ref(''),confirmPassword=ref(''),message=ref(''),router=useRouter();const save=async()=>{if(newPassword.value!==confirmPassword.value){message.value='两次新密码不一致';return}try{await apiRequest('/api/auth/password',{method:'PUT',body:JSON.stringify({currentPassword:currentPassword.value,newPassword:newPassword.value})});alert('密码已修改，请重新登录');await logout();await router.push('/login')}catch(e){message.value=e instanceof Error?e.message:'修改失败'}};</script>
<template><form class="card password-card" @submit.prevent="save"><h2>修改密码</h2><label>当前密码<input v-model="currentPassword" type="password" required></label><label>新密码（至少 8 位）<input v-model="newPassword" type="password" minlength="8" required></label><label>确认新密码<input v-model="confirmPassword" type="password" required></label><div v-if="message" class="form-error">{{message}}</div><button class="button button--primary">修改密码</button></form></template>
